<template><basic-container><el-card shadow="never">
  <div class="filters"><el-input v-model="query.keyword" clearable placeholder="事件、发送人、接收人或内容" @keyup.enter="search"/><el-select v-model="query.readStatus" clearable placeholder="全部阅读状态"><el-option label="未读" value="UNREAD"/><el-option label="已读" value="READ"/></el-select><el-button type="primary" @click="search">查询</el-button></div>
  <el-table :data="page.records" v-loading="loading" stripe><el-table-column prop="eventNo" label="事件编号" width="190"/><el-table-column prop="eventSummary" label="事件摘要" min-width="220" show-overflow-tooltip/><el-table-column prop="senderName" label="发送人" width="110"/><el-table-column prop="recipientName" label="接收人" width="110"/><el-table-column prop="notificationContent" label="通知内容" min-width="260" show-overflow-tooltip/><el-table-column prop="sendReason" label="发送原因" min-width="220" show-overflow-tooltip/><el-table-column label="阅读状态" width="100"><template #default="{row}"><el-tag :type="row.readTime?'success':'warning'">{{ row.readTime?'已读':'未读' }}</el-tag></template></el-table-column><el-table-column prop="readerName" label="阅读人" width="110"><template #default="{row}">{{ row.readerName||'—' }}</template></el-table-column><el-table-column prop="readTime" label="阅读时间" width="180"><template #default="{row}">{{ row.readTime||'—' }}</template></el-table-column><el-table-column prop="sentTime" label="发送时间" width="180"/></el-table>
  <el-pagination class="pager" background layout="total, sizes, prev, pager, next" :total="page.total" v-model:current-page="query.page" v-model:page-size="query.size" @change="load"/>
</el-card></basic-container></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{getAdminNotifications}from'@/api/smartReminder';const loading=ref(false),query=reactive({page:1,size:20,keyword:'',readStatus:''}),page=reactive({records:[],total:0});const load=async()=>{loading.value=true;try{Object.assign(page,(await getAdminNotifications(query)).data.data||{});}finally{loading.value=false;}};const search=()=>{query.page=1;load();};onMounted(load);</script>
<style scoped>.filters{display:flex;gap:10px;margin-bottom:16px}.filters .el-input{width:330px}.filters .el-select{width:160px}.pager{justify-content:flex-end;margin-top:18px}</style>
